#!/usr/bin/env node
/**
 * issue #43: generate a `settings.js` for editor A (an ordinary Node-RED
 * editor) that wires in issue #39's `remoteDeployStorage` adapter, pointed
 * at runner B's Admin API. This is the smallest mechanism that produces the
 * exact settings.js shape documented in this package's README ("Use an
 * existing Node-RED editor with a Temporal runtime (issue #39)") without
 * hand-editing it on every `make run`.
 *
 * Usage:
 *   node generate-editor-settings.js --user-dir <dir> --target <url> [--port <port>]
 *
 * Idempotent: the `credentialSecret` is generated once and persisted as
 * `<user-dir>/.credential-secret` so restarting the editor never invalidates
 * previously-deployed credentials; `settings.js` itself is always
 * regenerated so a changed `--target`/`--port` takes effect immediately.
 */

"use strict";

const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const { parseArgs } = require("util");

const { values } = parseArgs({
    options: {
        "user-dir": { type: "string" },
        target: { type: "string" },
        port: { type: "string" }
    },
    strict: true
});

if (!values["user-dir"] || !values.target) {
    console.error("Usage: generate-editor-settings.js --user-dir <dir> --target <url> [--port <port>]");
    process.exit(2);
}

const userDir = path.resolve(values["user-dir"]);
fs.mkdirSync(userDir, { recursive: true });

const secretFile = path.join(userDir, ".credential-secret");
let credentialSecret;
if (fs.existsSync(secretFile)) {
    credentialSecret = fs.readFileSync(secretFile, "utf8").trim();
} else {
    credentialSecret = crypto.randomBytes(32).toString("hex");
    fs.writeFileSync(secretFile, credentialSecret, { mode: 0o600 });
}

// Absolute paths: this generated settings.js is never published/portable,
// only ever run from THIS repo checkout, so absolute require() paths
// (rather than resolvable package names, which do not resolve from an
// arbitrary userDir in this monorepo layout) are correct here.
const remoteDeployStoragePath = path.join(__dirname, "..", "lib", "remoteDeployStorage.js");
const localfilesystemPath = path.join(__dirname, "..", "..", "..", "@node-red", "runtime", "lib", "storage", "localfilesystem");

const port = values.port || "1880";

const settingsContent = `/**
 * GENERATED by run/generate-editor-settings.js (issue #43) - do not edit by
 * hand, it is regenerated on every \`make run\`. See this package's README,
 * "Use an existing Node-RED editor with a Temporal runtime (issue #39)",
 * for what this wiring does and how to revert it.
 */
"use strict";

const { createRemoteDeployStorage } = require(${JSON.stringify(remoteDeployStoragePath)});
const localfilesystem = require(${JSON.stringify(localfilesystemPath)});

module.exports = {
    uiPort: ${JSON.stringify(port)},
    flowFile: "flows.json",

    // A and B must share the same credentialSecret so B can decrypt the
    // credential bundle A forwards on every Deploy.
    credentialSecret: ${JSON.stringify(credentialSecret)},

    // Wraps A's normal local storage: A's own flows/credentials/settings
    // are saved exactly as before, then forwarded to B as an additional
    // step. See lib/remoteDeployStorage.js's docblock for the full
    // save/forward/rollback semantics.
    storageModule: createRemoteDeployStorage(localfilesystem, {
        target: ${JSON.stringify(values.target)}
    }),

    // Editor A is design-time only: its own flows must never also run
    // locally, only on runner B.
    runtimeState: { enabled: true }
};
`;

fs.writeFileSync(path.join(userDir, "settings.js"), settingsContent);
console.log(`wrote ${path.join(userDir, "settings.js")} (target=${values.target})`);
